def transform(grid):
    out=[row[:] for row in grid]
    blocks=[]
    for r in range(len(grid)-1):
        for c in range(len(grid[0])-1):
            if grid[r][c]==2 and grid[r+1][c]==2 and grid[r][c+1]==2 and grid[r+1][c+1]==2:
                blocks.append((r,c))
    # Select the block furthest toward the lower-right.
    if blocks:
        r,c=max(blocks,key=lambda x:(x[0]+x[1],x[0],x[1]))
        for i in (r,r+1):
            for j in (c,c+1): out[i][j]=8
    return out
